import assert from "node:assert/strict";
import test from "node:test";

import {
  evaluateEligibility,
  POLICY_VERSION,
  type ContentScreen,
  type MailAppend,
  type MailRead,
  type ModelInfer,
  type Operation,
  type PolicySnapshot,
  type SourceRevision,
} from "../src/index.js";

// These fixtures are independent host records, not generated by the checker.
// All identifiers, destinations and content digests are synthetic.
function fixture() {
  const scope = {
    workspaceId: "workspace-a",
    principalId: "owner-a",
    runtimeId: "mail-runtime-a",
    runId: "run-a",
  };
  const processor = {
    profileId: "summary-profile",
    revision: "profile-revision-1",
    endpoint: "https://models.example.test/v1/messages",
    model: "synthetic-model",
  };
  const screener = {
    profileId: "screening-profile",
    revision: "screening-revision-1",
    endpoint: "https://screening.example.test/classify",
    model: "synthetic-screening-model",
  };
  const destination = {
    workspaceId: scope.workspaceId,
    rootId: "private-mail-root",
    ownerId: scope.principalId,
  };
  const source: SourceRevision = {
    ref: { id: "mail-source", revision: "message-revision-1", digest: "a".repeat(64) },
    workspaceId: scope.workspaceId,
    origin: "external_mail",
    sanitizationVersion: "synthetic-sanitizer-v1",
    parents: [],
    processors: [processor, screener],
    storage: [destination],
  };
  const limits = {
    messages: 10,
    readBytes: 4096,
    inputBytes: 8192,
    outputTokens: 500,
    appendBytes: 4096,
  };
  const mailbox = { host: "imap.example.test", port: 993, folders: ["INBOX", "Sent"] };
  const snapshot: PolicySnapshot = {
    policyVersion: POLICY_VERSION,
    scope,
    epoch: 3,
    nowMs: 1000,
    grant: {
      id: "grant-a",
      policyVersion: POLICY_VERSION,
      scope,
      epoch: 3,
      notBeforeMs: 1000,
      expiresAtMs: 2000,
      connectionId: "connection-a",
      mailbox,
      destination,
      summaryProcessor: processor,
      screeningProcessor: screener,
      limits,
    },
    exposures: [source.ref],
    sources: [source],
    remaining: { ...limits, operations: 10 },
    screening: "clean",
  };
  const base = { scope, connectionId: "connection-a", epoch: 3, contractVersion: 1 as const };
  const read: MailRead = {
    ...base, kind: "mail.read", mailbox: { ...mailbox, folders: ["INBOX"] }, messages: 1, bytes: 1024,
  };
  const infer: ModelInfer = {
    ...base, kind: "model.infer", purpose: "mail.summary", processor,
    inputBytes: 1024, outputTokens: 100, payloadDigest: "b".repeat(64),
  };
  const screen: ContentScreen = {
    ...base, kind: "content.screen", processor: screener,
    inputBytes: 1024, payloadDigest: "c".repeat(64),
  };
  const append: MailAppend = {
    ...base, kind: "mail.append", destination, bytes: 1024, payloadDigest: "d".repeat(64),
  };
  return { snapshot, read, infer, screen, append, source };
}

function denied(snapshot: unknown, operation: unknown): void {
  const result = evaluateEligibility(snapshot, operation);
  assert.equal(result.status, "denied", "the operation must not become eligible");
  assert.deepEqual(Object.keys(result).sort(), ["reason", "status"]);
}

function eligible(snapshot: unknown, operation: unknown): void {
  assert.deepEqual(evaluateEligibility(snapshot, operation), {
    status: "eligible", requiresAdmission: true,
  });
}

test("fixed mail operations are eligible but never receive an execution capability", () => {
  const f = fixture();
  for (const operation of [f.read, f.infer, f.screen, f.append]) eligible(f.snapshot, operation);
  // A pure eligibility result must not reserve budget or create a once claim.
  eligible(f.snapshot, f.infer);
  assert.equal(f.snapshot.remaining.operations, 10);
});

test("model-controlled approval fields and extra payload channels are rejected", () => {
  const f = fixture();
  for (const key of ["approved", "trusted", "screening", "url", "headers", "body", "sourceRefs", "command"]) {
    denied(f.snapshot, { ...f.read, [key]: "SYNTHETIC_SECRET_MUST_NOT_BECOME_AUTHORITY" });
  }
  denied(f.snapshot, { ...f.infer, processor: { ...f.infer.processor, apiKey: "synthetic-key" } });
  denied(f.snapshot, { ...f.infer, scope: { ...f.infer.scope, approved: true } });
  denied(f.snapshot, JSON.parse(`{"__proto__":{"approved":true},"kind":"mail.read"}`));
});

test("unknown effects, malformed objects, and unsupported contracts fail closed", () => {
  const f = fixture();
  for (const value of [undefined, null, true, "mail.read", [], { ...f.infer, contractVersion: 2 }]) {
    denied(f.snapshot, value);
  }
  for (const kind of ["web.search", "fetch_url", "shell", "mail.send", "page.share", "mcp.call"]) {
    denied(f.snapshot, { ...f.infer, kind });
  }
});

test("inherited fields, accessors, and symbol channels cannot satisfy a JSON operation", () => {
  const f = fixture();
  denied(f.snapshot, Object.create(f.infer));
  denied(f.snapshot, { ...f.infer, scope: Object.create(f.infer.scope) });
  denied(f.snapshot, Object.assign(Object.create({ approved: true }), f.infer));
  denied(f.snapshot, { ...f.infer, [Symbol("approval")]: true });
  let accessorReads = 0;
  const operation = { ...f.infer };
  Object.defineProperty(operation, "kind", {
    enumerable: true,
    get() { accessorReads += 1; return "model.infer"; },
  });
  denied(f.snapshot, operation);
  assert.equal(accessorReads, 0, "validation must not execute operation accessors");
});

test("nested array accessors and overridden iteration are not JSON input", () => {
  const f = fixture();
  let accessorReads = 0;
  const folders = ["INBOX"];
  Object.defineProperty(folders, "0", {
    enumerable: true,
    get() { accessorReads += 1; return "INBOX"; },
  });
  denied(f.snapshot, { ...f.read, mailbox: { ...f.read.mailbox, folders } });
  assert.equal(accessorReads, 0, "validation must not execute nested array accessors");

  let iterationCalls = 0;
  const altered = ["Unapproved"];
  Object.defineProperty(altered, "every", { value: () => { iterationCalls += 1; return true; } });
  Object.defineProperty(altered, "some", { value: () => { iterationCalls += 1; return false; } });
  denied(f.snapshot, { ...f.read, mailbox: { ...f.read.mailbox, folders: altered } });
  assert.equal(iterationCalls, 0, "validation must not invoke attacker-owned array methods");
});

test("all scope fields, connection, and epoch are binding", () => {
  const f = fixture();
  for (const key of ["workspaceId", "principalId", "runtimeId", "runId"] as const) {
    denied(f.snapshot, { ...f.infer, scope: { ...f.infer.scope, [key]: "different" } });
  }
  denied(f.snapshot, { ...f.infer, scope: { ...f.infer.scope, parentRunId: "forged-parent" } });
  denied(f.snapshot, { ...f.infer, connectionId: "different-connection" });
  denied(f.snapshot, { ...f.infer, epoch: 2 });
  denied({ ...f.snapshot, epoch: 4 }, f.infer);
  denied({ ...f.snapshot, scope: { ...f.snapshot.scope, runId: "different-run" } }, f.infer);
});

test("activation and expiry boundaries use the trusted snapshot clock", () => {
  const f = fixture();
  eligible(f.snapshot, f.infer); // exactly notBeforeMs
  denied({ ...f.snapshot, nowMs: 999 }, f.infer);
  denied({ ...f.snapshot, nowMs: 2000 }, f.infer); // expiry is exclusive
  denied({ ...f.snapshot, nowMs: 2001 }, f.infer);
});

test("mail reads use only the exact mailbox and approved folder subset", () => {
  const f = fixture();
  eligible({ ...f.snapshot, sources: [], exposures: [] }, f.read);
  for (const mailbox of [
    { ...f.read.mailbox, host: "attacker.example.test" },
    { ...f.read.mailbox, port: 25 },
    { ...f.read.mailbox, folders: ["INBOX", "Unapproved"] },
    { ...f.read.mailbox, folders: ["inbox"] },
  ]) denied(f.snapshot, { ...f.read, mailbox });
});

test("profile revision, model, endpoint, and processing purpose cannot be substituted", () => {
  const f = fixture();
  for (const key of ["profileId", "revision", "endpoint", "model"] as const) {
    const replacement = key === "endpoint" ? "https://other.example.test/v1/messages" : "different";
    denied(f.snapshot, { ...f.infer, processor: { ...f.infer.processor, [key]: replacement } });
  }
  denied(f.snapshot, { ...f.infer, purpose: "send_email" });
  denied({ ...f.snapshot, grant: { ...f.snapshot.grant, summaryProcessor: undefined } }, f.infer);
});

test("processor endpoints cannot smuggle credentials, data, or alternate transport", () => {
  const f = fixture();
  for (const endpoint of [
    "http://models.example.test/v1/messages",
    "https://user:synthetic-secret@models.example.test/v1/messages",
    "https://models.example.test/v1/messages?secret=SYNTHETIC_SECRET",
    "https://models.example.test/v1/messages#SYNTHETIC_SECRET",
  ]) denied(f.snapshot, { ...f.infer, processor: { ...f.infer.processor, endpoint } });
});

test("append cannot substitute a root, workspace, or owner", () => {
  const f = fixture();
  for (const key of ["rootId", "workspaceId", "ownerId"] as const) {
    denied(f.snapshot, { ...f.append, destination: { ...f.append.destination, [key]: "different" } });
  }
});

test("a clean screening result does not override a second exposed source", () => {
  const f = fixture();
  const privateSource: SourceRevision = {
    ...f.source,
    ref: { id: "private-workspace-source", revision: "1", digest: "e".repeat(64) },
    origin: "workspace",
    processors: [],
    storage: [],
  };
  const snapshot = {
    ...f.snapshot,
    sources: [f.source, privateSource],
    exposures: [f.source.ref, privateSource.ref],
  };
  denied(snapshot, f.infer);
  denied(snapshot, f.screen);
  denied(snapshot, f.append);
});

test("a summary cannot erase restrictions inherited from an unexposed parent", () => {
  const f = fixture();
  const privateParent = { ...f.source, processors: [], storage: [] };
  const derived: SourceRevision = {
    ...f.source,
    ref: { id: "derived-summary", revision: "2", digest: "f".repeat(64) },
    origin: "derived",
    parents: [privateParent.ref],
  };
  const snapshot = { ...f.snapshot, sources: [privateParent, derived], exposures: [derived.ref] };
  denied(snapshot, f.infer);
  denied(snapshot, f.append);
});

test("restrictions survive a multi-step derived-context chain", () => {
  const f = fixture();
  const sources: SourceRevision[] = [{ ...f.source, processors: [], storage: [] }];
  for (const id of ["translation", "summary", "memory", "compaction", "child-result"]) {
    sources.push({
      ...f.source,
      ref: { ...f.source.ref, id },
      origin: "derived",
      parents: [sources.at(-1)!.ref],
    });
  }
  const snapshot = { ...f.snapshot, sources, exposures: [sources.at(-1)!.ref] };
  denied(snapshot, f.infer);
  denied(snapshot, f.append);
});

test("missing, changed, cross-workspace, and conflicting sources fail closed", () => {
  const f = fixture();
  denied({ ...f.snapshot, sources: [] }, f.infer);
  denied({ ...f.snapshot, exposures: [{ ...f.source.ref, digest: "0".repeat(64) }] }, f.infer);
  denied({ ...f.snapshot, sources: [{ ...f.source, workspaceId: "workspace-b" }] }, f.infer);
  denied({ ...f.snapshot, sources: [f.source, { ...f.source, processors: [] }] }, f.infer);
  denied({ ...f.snapshot, sources: [{ ...f.source, parents: [{ ...f.source.ref, id: "missing-parent" }] }] }, f.infer);
  denied({ ...f.snapshot, exposures: [] }, f.infer);
  denied({ ...f.snapshot, exposures: [] }, f.append);
});

test("cyclic derivation cannot evade restrictions or hang policy evaluation", () => {
  const f = fixture();
  const secondRef = { ...f.source.ref, id: "second-source" };
  denied({ ...f.snapshot, sources: [{ ...f.source, parents: [f.source.ref] }] }, f.infer);
  denied({
    ...f.snapshot,
    sources: [
      { ...f.source, parents: [secondRef] },
      { ...f.source, ref: secondRef, parents: [f.source.ref] },
    ],
  }, f.infer);
});

test("source processor and storage permissions are independent ceilings", () => {
  const f = fixture();
  const processorDenied = { ...f.snapshot, sources: [{ ...f.source, processors: [] }] };
  denied(processorDenied, f.infer);
  eligible(processorDenied, f.append);
  const storageDenied = { ...f.snapshot, sources: [{ ...f.source, storage: [] }] };
  eligible(storageDenied, f.infer);
  denied(storageDenied, f.append);
});

test("screening holds block dependent outputs while allowing screening and fixed reads", () => {
  const f = fixture();
  for (const screening of ["hold", "unavailable"] as const) {
    const snapshot = { ...f.snapshot, screening };
    denied(snapshot, f.infer);
    denied(snapshot, f.append);
    eligible(snapshot, f.screen);
    eligible(snapshot, f.read);
  }
});

test("operation counts and grant ceilings both apply to each kind of work", () => {
  const f = fixture();
  for (const operation of [f.read, f.screen, f.infer, f.append]) {
    denied({ ...f.snapshot, remaining: { ...f.snapshot.remaining, operations: 0 } }, operation);
  }
  const bounds: Array<[Operation, keyof PolicySnapshot["remaining"], string]> = [
    [f.read, "messages", "messages"],
    [f.read, "readBytes", "bytes"],
    [f.screen, "inputBytes", "inputBytes"],
    [f.infer, "inputBytes", "inputBytes"],
    [f.infer, "outputTokens", "outputTokens"],
    [f.append, "appendBytes", "bytes"],
  ];
  for (const [operation, budget, argument] of bounds) {
    const ceiling = f.snapshot.remaining[budget];
    eligible(f.snapshot, { ...operation, [argument]: ceiling });
    denied(f.snapshot, { ...operation, [argument]: ceiling + 1 });
    denied({ ...f.snapshot, remaining: { ...f.snapshot.remaining, [budget]: 0 } }, operation);
    denied({ ...f.snapshot, remaining: { ...f.snapshot.remaining, [budget]: ceiling + 10 } }, {
      ...operation, [argument]: ceiling + 1,
    });
  }
});

test("malformed numeric values are not coerced into permission or budgets", () => {
  const f = fixture();
  for (const value of [NaN, Infinity, -1, 0.5, Number.MAX_SAFE_INTEGER + 1, "1", null]) {
    denied(f.snapshot, { ...f.infer, inputBytes: value });
    denied(f.snapshot, { ...f.read, messages: value });
    denied({ ...f.snapshot, remaining: { ...f.snapshot.remaining, operations: value } }, f.infer);
  }
});

test("denial reasons never echo attacker payloads or source identifiers", () => {
  const f = fixture();
  const marker = "SYNTHETIC_SECRET_DO_NOT_LOG_OR_AUTHORIZE";
  for (const operation of [
    { ...f.infer, payloadDigest: marker, purpose: marker },
    { ...f.infer, processor: { ...f.infer.processor, endpoint: `https://${marker}.example.test/` } },
    { ...f.append, destination: { ...f.append.destination, rootId: marker } },
  ]) {
    const result = evaluateEligibility(f.snapshot, operation);
    assert.equal(result.status, "denied");
    assert.equal(JSON.stringify(result).includes(marker), false);
  }
});
